def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    last_m, last_o = history[-1]
    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')
    if opp_defects == 0:
        if n >= 95:
            return 'D'
        return 'C'
    if n <= 4:
        if last_o == 'D' and last_m == 'C':
            return 'D'
        return 'C'
    window = history[-12:] if n >= 12 else history
    w = len(window)
    w_opp_d = sum(1 for _, o in window if o == 'D')
    w_opp_c = w - w_opp_d
    recent = history[-4:]
    r_opp_d = sum(1 for _, o in recent if o == 'D')
    r_opp_c = 4 - r_opp_d
    if last_o == 'C':
        if n >= 95 and opp_defects * 4 <= n:
            return 'D'
        if last_m == 'D' and r_opp_c >= 3:
            return 'C'
        return 'C'
    if w_opp_d >= w * 0.6 or (n >= 30 and opp_defects >= n * 0.5):
        return 'D'
    if r_opp_d >= 2:
        if last_m == 'D' and n >= 2 and history[-2][1] == 'D':
            if rng.random() < 0.5:
                return 'C'
        return 'D'
    if r_opp_c >= 3:
        return 'C'
    if n > 90:
        if opp_defects * 3 <= n:
            return 'C'
        if opp_defects * 2 > n:
            return 'D'
    if last_m == 'D' and rng.random() < 0.25:
        return 'C'
    return 'D'
